#!/usr/bin/env node
/**
 * Gallery Coverage Snapshot Worker
 *
 * Sibling to scripts/workers/r2-coverage-snapshot.mjs but for
 * `gallery_images.extracted_url` instead of `pages.archived_photo`. Gallery
 * thumbnails are generated by a separate pipeline (gallery-image-gen.ts) than
 * page archives, so the page-side r2 coverage snapshot doesn't catch books
 * where the gallery JPEGs are missing. The 2026-05-27 dedup review surfaced
 * entire books (Krestos Gospels, Lob der Narrheit, Herbarius latinus, …)
 * with 0% gallery-CDN coverage — gallery_images rows exist with valid-looking
 * `extracted_url` fields, but the underlying files 404 on R2.
 *
 * Strategy
 *   - For each book that has any gallery_images, HEAD-sample up to N rows
 *     in parallel (default 3) and record what fraction return 200.
 *   - Aggregate per-book / per-provider / library-wide.
 *   - Write to `system_config._id: 'gallery_coverage_snapshot'`.
 *
 * Tradeoffs
 *   - HEAD probes only — no body fetch, no hashing. Pure existence check.
 *   - We deliberately don't try to repair anything; that's a downstream
 *     concern (a script that calls /api/admin/generate-gallery-thumbnails
 *     for the affected rows).
 *   - Single sample per book is noisy but cheap; default of 3 gives a
 *     decent estimate and is what the page-side variant probe also uses.
 *
 * Usage
 *   set -a; source .env.production.local; set +a; \
 *     node scripts/workers/gallery-coverage-snapshot.mjs
 *   node scripts/workers/gallery-coverage-snapshot.mjs --samples=5 --concurrency=15
 *
 * Cron suggestion
 *   Every 12h alongside the r2-coverage snapshot.
 */
import { MongoClient } from 'mongodb';

const MONGODB_URI = process.env.MONGODB_URI;
if (!MONGODB_URI) { console.error('MONGODB_URI not set'); process.exit(1); }

const SAMPLES = parseInt(process.argv.find(a => a.startsWith('--samples='))?.split('=')[1] || '3', 10);
// undici default agent has ~10 connections per origin. Each book probes
// SAMPLES URLs in parallel, so book-level concurrency × SAMPLES must fit in
// the pool budget — 20 × 3 = 60 concurrent requests is comfortable.
const CONCURRENCY = parseInt(process.argv.find(a => a.startsWith('--concurrency='))?.split('=')[1] || '20', 10);
const HEAD_TIMEOUT_MS = 12_000;

async function headOnce(url) {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), HEAD_TIMEOUT_MS);
  try {
    const r = await fetch(url, { method: 'HEAD', signal: ctl.signal });
    return r.ok ? 'ok' : (r.status === 404 ? 'missing' : 'error');
  } catch {
    return 'error';
  } finally {
    clearTimeout(t);
  }
}

async function probeBook(db, bookId, samples) {
  // Pull up to `samples` random gallery_images for this book that have a URL.
  // $sample is the only DB call per book; the rest is pure HTTP I/O.
  const rows = await db.collection('gallery_images').aggregate([
    { $match: { book_id: bookId, extracted_url: { $type: 'string', $ne: '' } } },
    { $sample: { size: samples } },
    { $project: { _id: 0, extracted_url: 1 } },
  ], { allowDiskUse: false }).toArray();

  if (rows.length === 0) return { sampled: 0, ok: 0, missing: 0, error: 0 };

  const results = await Promise.all(rows.map(r => headOnce(r.extracted_url)));
  const ok = results.filter(r => r === 'ok').length;
  const missing = results.filter(r => r === 'missing').length;
  const error = results.filter(r => r === 'error').length;
  return { sampled: rows.length, ok, missing, error };
}

async function run() {
  const client = new MongoClient(MONGODB_URI, { socketTimeoutMS: 1800000 });
  await client.connect();
  const db = client.db('bookstore');
  const start = Date.now();

  console.log(`[gallery-coverage-snapshot] Starting at ${new Date().toISOString()}`);

  // Get all books with at least one gallery_images row
  const candidates = await db.collection('gallery_images').aggregate([
    { $group: { _id: '$book_id', n: { $sum: 1 } } },
    { $sort: { n: -1 } },
  ], { allowDiskUse: true, maxTimeMS: 300_000 }).toArray();

  console.log(`  books with gallery_images: ${candidates.length}`);

  // Pull provider/title for the reports
  const bookIds = candidates.map(c => c._id).filter(Boolean);
  const books = await db.collection('books').find(
    { id: { $in: bookIds } },
    { projection: { id: 1, title: 1, slug: 1, language: 1, 'image_source.provider': 1, _id: 0 } }
  ).toArray();
  const bookMeta = new Map(books.map(b => [b.id, b]));

  const byProvider = {};
  let totalSampled = 0;
  let totalOk = 0;
  let totalMissing = 0;
  let totalError = 0;
  const fullCoverageBooks = [];
  const partialBooks = [];
  const noCoverageBooks = [];

  // Process books in batches of CONCURRENCY
  for (let i = 0; i < candidates.length; i += CONCURRENCY) {
    const batch = candidates.slice(i, i + CONCURRENCY);
    const results = await Promise.all(batch.map(c => probeBook(db, c._id, SAMPLES)));

    for (let j = 0; j < batch.length; j++) {
      const c = batch[j];
      const r = results[j];
      const meta = bookMeta.get(c._id);
      const provider = meta?.image_source?.provider || 'unknown';

      totalSampled += r.sampled;
      totalOk += r.ok;
      totalMissing += r.missing;
      totalError += r.error;

      if (!byProvider[provider]) byProvider[provider] = { books: 0, sampled: 0, ok: 0, missing: 0, error: 0, total_rows: 0 };
      byProvider[provider].books += 1;
      byProvider[provider].sampled += r.sampled;
      byProvider[provider].ok += r.ok;
      byProvider[provider].missing += r.missing;
      byProvider[provider].error += r.error;
      byProvider[provider].total_rows += c.n;

      if (r.sampled === 0) continue; // no URLs to probe — out of scope
      const okRatio = r.ok / r.sampled;
      const bookRecord = {
        id: c._id,
        title: meta?.title || c._id,
        slug: meta?.slug,
        provider,
        language: meta?.language,
        gallery_rows: c.n,
        sampled: r.sampled,
        ok: r.ok,
        missing: r.missing,
        error: r.error,
        ok_pct: Math.round(okRatio * 1000) / 10,
      };
      if (okRatio >= 0.99) fullCoverageBooks.push(bookRecord);
      else if (okRatio === 0) noCoverageBooks.push(bookRecord);
      else partialBooks.push(bookRecord);
    }

    const done = Math.min(i + CONCURRENCY, candidates.length);
    process.stderr.write(`\r  probed ${done}/${candidates.length} books (${totalOk}/${totalSampled} samples ok)`);
  }
  process.stderr.write('\n');

  // Rank lists by impact (most gallery_rows on the broken side first)
  noCoverageBooks.sort((a, b) => b.gallery_rows - a.gallery_rows);
  partialBooks.sort((a, b) => (b.gallery_rows * (1 - b.ok_pct / 100)) - (a.gallery_rows * (1 - a.ok_pct / 100)));

  const snapshot = {
    _id: 'gallery_coverage_snapshot',
    computed_at: new Date(),
    computation_ms: Date.now() - start,
    settings: { samples_per_book: SAMPLES, concurrency: CONCURRENCY },
    library: {
      books_probed: candidates.length,
      total_gallery_rows: candidates.reduce((s, c) => s + c.n, 0),
      samples_total: totalSampled,
      samples_ok: totalOk,
      samples_missing: totalMissing,
      samples_error: totalError,
      ok_pct: totalSampled > 0 ? Math.round((totalOk / totalSampled) * 1000) / 10 : 0,
    },
    coverage_buckets: {
      full: fullCoverageBooks.length,
      partial: partialBooks.length,
      none: noCoverageBooks.length,
    },
    by_provider: byProvider,
    no_coverage_books_top200: noCoverageBooks.slice(0, 200),
    partial_books_top200: partialBooks.slice(0, 200),
    no_coverage_books_count: noCoverageBooks.length,
    partial_books_count: partialBooks.length,
  };

  await db.collection('system_config').replaceOne(
    { _id: 'gallery_coverage_snapshot' },
    snapshot,
    { upsert: true }
  );

  const elapsed = ((Date.now() - start) / 1000).toFixed(1);
  console.log(`[gallery-coverage-snapshot] Done in ${elapsed}s`);
  console.log(`  Library: ${snapshot.library.ok_pct}% OK (${totalOk}/${totalSampled} samples)`);
  console.log(`  Buckets: full=${fullCoverageBooks.length}, partial=${partialBooks.length}, none=${noCoverageBooks.length}`);
  if (noCoverageBooks.length) {
    console.log(`  Top 5 no-coverage books (by gallery_rows):`);
    for (const b of noCoverageBooks.slice(0, 5)) {
      console.log(`    ${b.gallery_rows.toString().padStart(4)} rows  "${b.title.slice(0, 60)}"  [${b.provider}]`);
    }
  }
  await client.close();
}

run().catch(err => { console.error(err); process.exit(1); });
